  'room.cocina.desc': 'Nutrition : note tes repas, macros, eau et ton plan de la semaine.',
  'room.ejercicio.desc': 'Routines de force, d’endurance et de souplesse avec objectifs.',
  'room.recamara.desc': 'Suis ton repos et écris ton carnet de souvenirs personnel.',
  'room.descanso.desc': 'Ton sommeil sous forme de ciel nocturne : horaire, alarme, score et journal de nuit.',
  'room.anecdotario.desc': 'Ton journal personnel : souvenirs avec photos et humeur du jour.',
  'room.despacho.desc':
    'Finances : budget avec dépenses et revenus (fixes et variables), objectifs (calculatrices financières, épargne/investissement, dettes) avec simulateurs, et marchés en direct.',
  'room.biblioteca.desc': 'Encyclopédie conversationnelle : discussions avec l’IA, articles wiki et sessions d’étude.',
  'room.entretenimiento.desc': 'Archive de films, séries, livres et jeux de société.',
  'room.sala.desc': 'Planifie tes voyages : itinéraire, dépenses, liste de tâches et liste d’envies.',
  'room.jardin.desc': 'Calme : méditations guidées, respiration et journal de gratitude.',
  'room.garage.desc': 'Entretien de tes véhicules et de leurs révisions.',
  'room.diario.desc': 'Centre d’actualités quotidiennes, par catégorie.',
  'room.hobbies.desc': 'Tes loisirs et projets créatifs.',
  'room.idiomas.desc':
    'Apprends des langues : tuteur IA, vocabulaire à répétition espacée, programme par niveau et exercices.',
  'room.calendario.desc': 'Ton calendrier : événements et routines par jour, semaine et mois.',
  'room.caminos.desc': 'Trace des circuits de course, des rails de train et des montagnes russes sur le plan.',
  'room.canchas.desc': 'Place des terrains de foot, tennis, basket et baseball sur le plan.',
  'room.huerto.desc': 'Prépare des parcelles, sème des cultures, arrose-les et récolte en temps réel.',
  'room.granja.desc':
    'Élève poules, cochons, chèvres, moutons, vaches et chevaux, et cultive leur nourriture dans le même éditeur.',
  'room.ideas.desc':
    'Ton journal d’idées et remue-méninges, dix formats de carte conceptuelle sur une toile libre (carte mentale, arbre, chronologie, cycle, pyramide, Venn…) et huit diagrammes pour décider (avantages et inconvénients, champ de forces, SWOT, Eisenhower, arbre de décision, tier list, matrice de décision pondérée et Ishikawa), à la main ou avec l’IA.',
  'room.computo.desc':
    'Salle de calcul : une calculatrice scientifique avec son formulaire accroché (Mathématiques, Physique et Chimie incluses et modifiables) et huit modes — un traceur avec quatre types (2D, polaire, paramétrique et surface 3D), binaire et hexadécimal, matrices, systèmes d’équations, conversion d’unités, pourboire et règle de trois ; et des feuilles de calcul qui s’exportent en Excel et PDF.',
