  'ideas.matriz.ayuda':
    'Touche un nom pour le changer, le poids pour augmenter l’importance de ce critère, et chaque case pour noter de 1 à 5. Le total est déjà multiplié par les poids.',
  'ideas.ejemplo.ver': 'Voir un exemple',
  'ideas.ejemplo.chip': 'Exemple',
  'ideas.ejemplo.comoFunciona': 'Comment fonctionne ce format ?',
  'ideas.guia.mental':
    'Une carte mentale ouvre un sujet dans toutes les directions : l’idée au centre, les grandes branches autour et leurs détails qui en découlent. Elle sert à vider ta tête avant de choisir un ordre.',
  'ideas.guia.arbol':
    'L’arbre va du général au spécifique, comme un organigramme. Utilise-le quand tu as des catégories qui se divisent en sous-catégories, pas des idées éparses.',
  'ideas.guia.etimologia':
    'L’arbre étymologique décompose un mot : d’où il vient, ce qu’il signifie, comment il s’utilise et quels mots appartiennent à sa famille. Pratique pour creuser un concept avant un remue-méninges ou pour trouver un nom.',
  'ideas.tipo.etimologia': 'Arbre étymologique',
  'ideas.tipoDesc.etimologia': 'Un mot décomposé : son origine, ses sens, son usage et sa famille.',
  'ideas.guia.llaves':
    'Les accolades divisent un tout en ses parties, de gauche à droite — le plan classique. Utile pour décomposer quelque chose et voir de quoi il est fait.',
  'ideas.guia.circulo':
    'Le cercle place un sujet au centre et l’entoure de tout ce que tu sais à son sujet, sans hiérarchie. Pratique pour explorer un concept ou réviser avant un examen.',
  'ideas.guia.flujo':
    'Le logigramme enchaîne des étapes avec des flèches. Touche une étape et utilise le bouton de forme pour en faire un début, une décision ou une fin : les losanges sont les questions oui/non.',
  'ideas.guia.linea':
    'La chronologie trie par date : chaque jalon se place alternativement au-dessus et en dessous de la ligne, avec ses détails vers l’extérieur. Commence le jalon par l’année et il se lit tout seul.',
  'ideas.guia.ciclo':
    'Le cycle enchaîne des étapes qui recommencent. Ajoute chaque étape depuis la racine — touche l’arrière-plan pour qu’elle ne dépende pas de la précédente — et elles se répartissent seules autour du cercle.',
  'ideas.guia.piramide':
    'La pyramide empile des niveaux : chacun repose sur celui du dessous, donc la base est ce que tu dois couvrir en premier. Touche deux fois le nom d’un niveau pour le changer.',
  'ideas.guia.venn':
    'Le Venn oppose deux ensembles, et ce qu’ils partagent tombe là où ils se chevauchent. Choisis la zone dans la barre du bas avant d’ajouter, ou fais glisser un élément sur un autre et il se déplace tout seul.',
  'ideas.guia.comparacion':
    'La comparaison met deux sujets en colonnes et ce qu’ils partagent au milieu. C’est le Venn version tableau : plus rapide à lire quand il y a beaucoup de points de chaque côté.',
  'ideas.guia.proscontras':
    'Chaque point pèse de 1 à 5 : sélectionne-le et utilise − + dans la barre du bas. Chaque colonne s’additionne en bas, donc la décision ne se résume plus à « quelle liste est la plus longue ».',
  'ideas.guia.fuerzas':
    'Le champ de forces regarde un changement : ce qui le pousse à gauche, ce qui le freine à droite, chacun avec son poids. Si le côté droit l’emporte, attaque d’abord la force la plus lourde.',
  'ideas.guia.foda':
    'Les forces et les faiblesses sont LES TIENNES ; les opportunités et les menaces viennent de l’extérieur. En cas de doute, demande-toi si ça dépend de toi ou non.',
  'ideas.guia.eisenhower':
    'Important en haut, urgent à gauche. Le quadrant « à planifier » est celui qui fait vraiment avancer les choses : s’il reste vide, tu passes ta journée à éteindre des incendies.',
  'ideas.guia.decision':
    'Chaque branche est une option, et ses conséquences en découlent. Écris-les même quand elles semblent évidentes : ce qui n’est pas écrit ne se compare à rien.',
  'ideas.guia.tier':
    'S est le meilleur et D le pire. Ce que tu ne peux pas encore classer attend en bas dans « Non classé » : fais-le glisser vers sa rangée une fois sûr.',
  'ideas.guia.ishikawa':
    'La tête est le problème et chaque arête une famille de causes (méthode, équipement, matériaux, mesure…). Cherche des CAUSES, pas des solutions : elles viendront plus tard.',
