  'chat.manual.aviso.caminos':
    'Les commandes de construction ouvrent un éditeur plein écran : le chat se ferme jusqu’à ce que tu quittes avec ✕. Les actions d’entretien fonctionnent sans quitter le chat.',
  'chat.manual.aviso.granja':
    'Les commandes de construction ouvrent un éditeur plein écran : le chat se ferme jusqu’à ce que tu quittes avec ✕. Les actions d’entretien fonctionnent sans quitter le chat.',
  'chat.manual.aviso.huerto':
    'Les commandes de construction ouvrent un éditeur plein écran : le chat se ferme jusqu’à ce que tu quittes avec ✕. Les actions d’entretien fonctionnent sans quitter le chat.',
